def solid_rects(g, minside=2):
    n=len(g); m=len(g[0]); res=[]
    for i in range(n):
        for j in range(m):
            c=g[i][j]
            # max extension
            H=i+1
            while H<n and g[H][j]==c: H+=1
            W=j+1
            while W<m and g[i][W-1]==c: W+=1
            if H*W<4: continue
            # must be exact rectangle: verify
            if all(g[r][cl]==c for r in range(i,H) for cl in range(j,W)):
                res.append((H-i,W-j,c,i,j,H,W))
